"use strict";

/**
 * GET /api/admin/openapi.json: OpenAPI 3.1 of the REST surface under /api, generated by
 * walking the mounted Express routers (method, path, path parameters), plus hand-written
 * summaries and tags for the main admin endpoints. The walk runs once per app and is
 * cached (routes do not change at runtime).
 *
 * Express 4 keeps a router's mount path only as a RegExp; mountPath() turns the
 * patterns Express generates back into a path ("/api/admin", "/api/servers/:id").
 */

