const TAG_NAMES = {
  overview: "Admin: Overview",
  directory: "Admin: Users",
  people: "Admin: Users",
  analytics: "Admin: Analytics",
  signupStats: "Admin: Analytics",
  retention: "Admin: Analytics",
  economy: "Admin: Economy",
  topUsers: "Admin: Analytics",
  reports: "Admin: Reports",
  moderation: "Admin: Moderation",
  accessBans: "Admin: Moderation",
  dmReview: "Admin: Messages",
  serverReview: "Admin: Servers",
  suspicious: "Admin: Anti-bot",
  premium: "Admin: Premium",
  shop: "Admin: Shop",
  casino: "Admin: DesCoin",
  promo: "Admin: Promo",
  specialBadges: "Admin: Badges",
  announcements: "Admin: Announcements",
  livepopup: "Admin: Live popup",
  system: "Admin: System",
  security: "Admin: Security",
  errors: "Admin: Errors",
  feedback: "Admin: Feedback",
  audit: "Admin: Audit log",
  agent: "Admin: Agent",
  staff: "Admin: Staff",
  maintenance: "Admin: Maintenance",
};

let cache = null; // { app, doc }

/** Mount path of a router layer, from the RegExp Express 4 builds for app.use(path). */
function mountPath(layer) {
  if (!layer?.regexp) return "";
  if (layer.regexp.fast_slash) return "";
  let src = layer.regexp.source;
  src = src.replace(/^\^/, "").replace(/\\\/\?\(\?=\\\/\|\$\)$/i, "").replace(/\(\?=\\\/\|\$\)$/i, "").replace(/\\\/\?$/, "");
  let i = 0;
  const keys = layer.keys || [];
  // "(?:\/([^/]+?))" (or "[^\/]" on older engines) is one ":param" segment.
  src = src.replace(/\(\?:\\\/\(\[\^\\?\/\]\+\?\)\)\??/g, () => `\\/:${keys[i++]?.name ?? `p${i}`}`);
  if (/[()[\]|*+?{}^$]/.test(src.replace(/\\\//g, ""))) return null; // array / regexp mounts are skipped
  return src.replace(/\\\//g, "/").replace(/\\(.)/g, "$1");
}

function walk(stack, prefix, out) {
  for (const layer of stack || []) {
    if (layer.route) {
      const paths = Array.isArray(layer.route.path) ? layer.route.path : [layer.route.path];
      for (const p of paths) {
        if (typeof p !== "string" || p.includes("*")) continue;
        for (const m of METHODS) if (layer.route.methods?.[m]) out.push({ method: m, path: `${prefix}${p === "/" && prefix ? "" : p}` || "/" });
      }
    } else if (layer.name === "router" && layer.handle?.stack) {
      const mp = mountPath(layer);
      if (mp === null) continue;
      walk(layer.handle.stack, `${prefix}${mp}`, out);
    }
  }
  return out;
}

function toOpenApiPath(path) {
  return path.replace(/:([A-Za-z0-9_]+)\??/g, "{$1}").replace(/\/{2,}/g, "/");
}

function tagFor(apiPath) {
  const p = apiPath.replace(/^\/api/, "");
  if (p.startsWith("/admin/")) {
    const rel = p.slice("/admin".length).replace(/\{[^}]+\}/g, "x");
    const section = sectionForPath(rel);
    return TAG_NAMES[section] || "Admin";
  }
  const seg = p.split("/")[1] || "api";
  return `App: ${seg}`;
}

/** [{ method, path ("/api/..." in OpenAPI form), summary, tag }] sorted and de-duplicated. */
function operations(app) {
  const stack = app?._router?.stack || [];
  const raw = walk(stack, "", []);
  const seen = new Set();
  const ops = [];
  for (const r of raw) {
    const path = toOpenApiPath(r.path);
    if (!path.startsWith("/api/")) continue;
    const key = `${r.method} ${path}`;
    if (seen.has(key)) continue;
    seen.add(key);
    const rel = path.replace(/^\/api/, "");
    ops.push({ method: r.method, path, summary: SUMMARIES[`${r.method.toUpperCase()} ${rel}`] || null, tag: tagFor(path) });
  }
  ops.sort((a, b) => a.path.localeCompare(b.path) || METHODS.indexOf(a.method) - METHODS.indexOf(b.method));
  return ops;
}

function build(app, { serverUrl = "https://des-call.onrender.com" } = {}) {
  if (cache && cache.app === app && cache.serverUrl === serverUrl) return cache.doc;
  const ops = operations(app);
  const paths = {};
  const tags = new Set();
  for (const op of ops) {
    const params = [...op.path.matchAll(/\{([^}]+)\}/g)].map((m) => ({ name: m[1], in: "path", required: true, schema: { type: "string" } }));
    const destructive = require("./core").destructiveKind(op.method, op.path.replace(/\{[^}]+\}/g, "x"));
    paths[op.path] = paths[op.path] || {};
    tags.add(op.tag);
    paths[op.path][op.method] = {
      operationId: `${op.method}_${op.path.replace(/^\/api\//, "").replace(/[{}]/g, "").replace(/[^A-Za-z0-9]+/g, "_")}`.replace(/_+$/, ""),
      summary: op.summary || `${op.method.toUpperCase()} ${op.path}`,
      tags: [op.tag],
      ...(params.length ? { parameters: params } : {}),
      ...(["post", "put", "patch"].includes(op.method) ? { requestBody: { required: false, content: { "application/json": { schema: { type: "object" } } } } } : {}),
      ...(destructive ? { "x-destructive": destructive } : {}),
      responses: {
        200: { description: "OK", content: { "application/json": { schema: { type: "object" } } } },
        401: { description: "Missing or invalid token" },
        403: { description: "Not allowed" },
      },
    };
  }
  const doc = {
    openapi: "3.1.0",
    info: {
      title: "Descall API",
      version: "1.0.0",
      description:
        "Admin and app REST API of Descall, generated from the server's routers. Authenticate with `Authorization: Bearer dsk_admin_…` (an owner admin token) or an owner session. " +
        "Admin endpoints live under /api/admin. Operations marked x-destructive (ban, delete, descoin, broadcast) change things for real.",
    },
    servers: [{ url: serverUrl }],
    security: [{ bearerAuth: [] }],
    tags: [...tags].sort().map((name) => ({ name })),
    paths,
    components: {
      securitySchemes: {
        bearerAuth: { type: "http", scheme: "bearer", description: "Admin token (dsk_admin_…) or a session JWT." },
      },
    },
  };
  cache = { app, serverUrl, doc };
  return doc;
}

/** Compact list for MCP describe_api: "METHOD /api/path  summary", filtered by text or tag. */
function describe(app, { q = "", tag = "", limit = 400 } = {}) {
  const needle = String(q || "").toLowerCase();
  const t = String(tag || "").toLowerCase();
  const ops = operations(app).filter((op) => {
    if (t && !op.tag.toLowerCase().includes(t)) return false;
    if (needle && !`${op.method} ${op.path} ${op.summary || ""}`.toLowerCase().includes(needle)) return false;
    return true;
  });
  return {
    total: ops.length,
    tags: [...new Set(operations(app).map((o) => o.tag))].sort(),
    operations: ops.slice(0, Math.max(1, Math.min(1000, limit))).map((op) => ({
      method: op.method.toUpperCase(),
      path: op.path,
      tag: op.tag,
      ...(op.summary ? { summary: op.summary } : {}),
    })),
  };
}

function __resetForTests() {
  cache = null;
}

module.exports = { build, describe, operations, mountPath, SUMMARIES, __resetForTests };
